/// Generated files for fake-mode seeding: real images (several sizes), an animated GIF, PDFs and opaque blobs.
struct FakeLibrary: Sendable {
    struct Item: Sendable {
        let name: String
        let contentType: String
        let data: Data
    }

    static let shared = FakeLibrary()

    static let gifURL = URL(string: "https://fake-emoji.example/gif/party.gif")!
    static let gifData: Data = FakeMedia.gif(
        width: 240, height: 160,
        colors: [
            .init(red: 230, green: 80, blue: 90), .init(red: 240, green: 170, blue: 50),
            .init(red: 70, green: 190, blue: 110),
            .init(red: 60, green: 130, blue: 230), .init(red: 150, green: 90, blue: 220),
        ], frameDelay: 0.35)

    let landscape = Item(
        name: "onboarding-flow.png", contentType: "image/png",
        data: render(width: 1280, height: 720, hue: 0.58, label: "Onboarding flow", type: .png))
    let portrait = Item(
        name: "mobile-mockup.jpg", contentType: "image/jpeg",
        data: render(width: 720, height: 1080, hue: 0.08, label: "Mobile mockup", type: .jpeg))
    let small = Item(
        name: "icon-sketch.png", contentType: "image/png",
        data: render(width: 200, height: 120, hue: 0.33, label: "Icon", type: .png))
    let square = Item(
        name: "IMG_4021.heic", contentType: "image/heic",
        data: render(width: 600, height: 600, hue: 0.78, label: "Offsite", type: .jpeg))
    let large = Item(
        name: "site-photo-large.jpg", contentType: "image/jpeg",
        data: render(width: 2400, height: 1600, hue: 0.45, label: "Site photo", type: .jpeg))
    let pdf = Item(
        name: "Release-notes-4.2.pdf", contentType: "application/pdf",
        data: FakeMedia.pdf(pages: 3, title: "Release notes 4.2"))
    let gif = Item(name: "celebrate.gif", contentType: "image/gif", data: gifData)

    /// Picks generated bytes for an attachment; ids like `show-png` choose a specific image, others hash.
    func item(type: String, id: String) -> Item {
        let lower = type.lowercased()
        let pick = abs(id.unicodeScalars.reduce(7) { ($0 &* 31) &+ Int($1.value) })
        switch id {
        case "show-png", "show-flow": return landscape
        case "show-jpg": return portrait
        case "show-heic": return square
        case "show-gif": return gif
        default: break
        }
        if lower == "image/gif" { return gif }
        if lower.hasPrefix("image/") {
            let options = [landscape, portrait, small, square, large]
            return options[pick % options.count]
        }
        if lower == "application/pdf" { return pdf }
        return blob(id, type)
    }

    /// Opaque stand-ins for types the app only opens in other apps.
    func blob(_ name: String, _ contentType: String) -> Item {
        Item(name: name, contentType: contentType, data: Data(repeating: 0x20, count: 4096))
    }

    /// Items for random attachments in ordinary history.
    var pool: [Item] {
        [
            landscape, portrait, small, square, pdf, gif,
            blob("assets-export.zip", "application/zip"),
            blob("Proposal-v2.docx", FakeScript.Mime.docx),
            blob("Forecast.xlsx", FakeScript.Mime.xlsx),
            blob("walkthrough.mp4", "video/mp4"),
        ]
    }

    // MARK: Rendering

    private static func render(width: Int, height: Int, hue: Double, label: String, type: UTType) -> Data {
        let space = CGColorSpace(name: CGColorSpace.sRGB)!
        guard
            let context = CGContext(
                data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0, space: space,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
        else { return Data() }
        let top = color(hue, 0.45, 0.95)
        let bottom = color(hue + 0.07, 0.75, 0.55)
        if let gradient = CGGradient(colorsSpace: space, colors: [top, bottom] as CFArray, locations: [0, 1]) {
            context.drawLinearGradient(
                gradient, start: CGPoint(x: 0, y: CGFloat(height)), end: CGPoint(x: CGFloat(width), y: 0), options: [])
        }
        let unit = CGFloat(min(width, height))
        context.setFillColor(CGColor(gray: 1, alpha: 0.18))
        context.fillEllipse(in: CGRect(x: unit * 0.1, y: unit * 0.15, width: unit * 0.55, height: unit * 0.55))
        context.setFillColor(CGColor(gray: 0, alpha: 0.12))
        context.fill(CGRect(x: CGFloat(width) * 0.45, y: unit * 0.2, width: CGFloat(width) * 0.4, height: unit * 0.3))
        let font = CTFontCreateWithName("Helvetica-Bold" as CFString, unit * 0.09, nil)
        let text = NSAttributedString(
            string: "\(label)  \(width)x\(height)",
            attributes: [
                NSAttributedString.Key(kCTFontAttributeName as String): font,
                NSAttributedString.Key(kCTForegroundColorAttributeName as String): CGColor(gray: 1, alpha: 0.95),
            ])
        context.textPosition = CGPoint(x: unit * 0.06, y: CGFloat(height) - unit * 0.14)
        CTLineDraw(CTLineCreateWithAttributedString(text), context)
        guard let image = context.makeImage() else { return Data() }
        let output = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(output, type.identifier as CFString, 1, nil) else {
            return Data()
        }
        CGImageDestinationAddImage(
            destination, image, [kCGImageDestinationLossyCompressionQuality: 0.8] as CFDictionary)
        CGImageDestinationFinalize(destination)
        return output as Data
    }

    private static func color(_ hue: Double, _ saturation: Double, _ brightness: Double) -> CGColor {
        let h = hue - hue.rounded(.down)
        let i = Int(h * 6)
        let f = h * 6 - Double(i)
        let p = brightness * (1 - saturation)
        let q = brightness * (1 - f * saturation)
        let t = brightness * (1 - (1 - f) * saturation)
        let (r, g, b): (Double, Double, Double) =
            switch i % 6 {
            case 0: (brightness, t, p)
            case 1: (q, brightness, p)
            case 2: (p, brightness, t)
            case 3: (p, q, brightness)
            case 4: (t, p, brightness)
            default: (brightness, p, q)
            }
        return CGColor(srgbRed: r, green: g, blue: b, alpha: 1)
    }
}

/// Serves the generated GIF for `https://fake-emoji.example/gif/…`, standing in for a token-less media host.
final class FakeGifHost: URLProtocol, @unchecked Sendable {
    override class func canInit(with request: URLRequest) -> Bool {
        request.url?.host()?.lowercased() == "fake-emoji.example" && request.url?.path.hasPrefix("/gif/") == true
    }

    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    override func startLoading() {
        guard let url = request.url else {
            client?.urlProtocol(self, didFailWithError: URLError(.badURL))
            return
        }
        let data = FakeLibrary.gifData
        let response = HTTPURLResponse(
            url: url, statusCode: 200, httpVersion: "HTTP/1.1",
            headerFields: ["Content-Type": "image/gif", "Content-Length": String(data.count)])!
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: data)
        client?.urlProtocolDidFinishLoading(self)
    }

    override func stopLoading() {}
}
